import { test, expect, Page } from '@playwright/test';

test.describe('Google OAuth Login', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000/login');
  });

  test('should display Google login button on login page', async () => {
    const googleLoginButton = page.getByRole('button', { name: /sign in with google/i });
    await expect(googleLoginButton).toBeVisible();
  });

  test('should redirect to Google OAuth consent screen when clicking Google login button', async () => {
    const googleLoginButton = page.getByRole('button', { name: /sign in with google/i });

    // Listen for popup window
    const [popup] = await Promise.all([
      page.waitForEvent('popup'),
      googleLoginButton.click()
    ]);

    // Verify we're on Google's domain
    await expect(popup).toHaveURL(/accounts\.google\.com/);

    // Verify Google login page elements are present
    const emailInput = popup.getByLabel(/email or phone/i);
    await expect(emailInput).toBeVisible();

    await popup.close();
  });

  test('should successfully authenticate and redirect to dashboard after Google OAuth', async ({ context }) => {
    // Mock the Google OAuth callback
    await context.addInitScript(() => {
      window.localStorage.setItem('auth_token', 'mock_google_token_12345');
      window.localStorage.setItem('user_email', 'testuser@gmail.com');
    });

    const googleLoginButton = page.getByRole('button', { name: /sign in with google/i });

    // Simulate successful OAuth flow by directly navigating to callback URL
    await page.goto('http://localhost:3000/auth/google/callback?code=mock_auth_code&state=mock_state');

    // Wait for redirect to dashboard
    await page.waitForURL('**/dashboard');

    // Verify user is logged in
    const userGreeting = page.getByText(/welcome/i);
    await expect(userGreeting).toBeVisible();

    // Verify auth token is stored
    const authToken = await page.evaluate(() => localStorage.getItem('auth_token'));
    expect(authToken).toBeTruthy();
  });

  test('should handle Google OAuth errors gracefully', async () => {
    // Navigate to callback with error parameter
    await page.goto('http://localhost:3000/auth/google/callback?error=access_denied&error_description=User+denied+access');

    // Verify error message is displayed
    const errorMessage = page.getByText(/access denied|authentication failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is redirected back to login
    await expect(page).toHaveURL(/login/);
  });

  test('should persist user session after Google OAuth login', async ({ context }) => {
    // Set up authenticated session
    await context.addInitScript(() => {
      window.localStorage.setItem('auth_token', 'mock_google_token_12345');
      window.localStorage.setItem('user_email', 'testuser@gmail.com');
    });

    // Navigate to dashboard
    await page.goto('http://localhost:3000/dashboard');

    // Verify user is still logged in
    const userEmail = page.getByText(/testuser@gmail\.com/i);
    await expect(userEmail).toBeVisible();

    // Verify logout button is available
    const logoutButton = page.getByRole('button', { name: /logout|sign out/i });
    await expect(logoutButton).toBeVisible();
  });

  test('should clear session on logout after Google OAuth login', async ({ context }) => {
    // Set up authenticated session
    await context.addInitScript(() => {
      window.localStorage.setItem('auth_token', 'mock_google_token_12345');
      window.localStorage.setItem('user_email', 'testuser@gmail.com');
    });

    await page.goto('http://localhost:3000/dashboard');

    // Click logout button
    const logoutButton = page.getByRole('button', { name: /logout|sign out/i });
    await logoutButton.click();

    // Verify redirect to login page
    await expect(page).toHaveURL(/login/);

    // Verify auth token is cleared
    const authToken = await page.evaluate(() => localStorage.getItem('auth_token'));
    expect(authToken).toBeNull();
  });

  test('should handle network errors during Google OAuth flow', async () => {
    // Simulate network error
    await page.route('**/auth/google/callback**', route => {
      route.abort('failed');
    });

    await page.goto('http://localhost:3000/auth/google/callback?code=mock_code&state=mock_state');

    // Verify error handling
    const errorElement = page.getByText(/network error|connection failed|try again/i);
    await expect(errorElement).toBeVisible();
  });

  test('should validate CSRF token in Google OAuth callback', async () => {
    // Attempt callback with mismatched state (CSRF token)
    await page.goto('http://localhost:3000/auth/google/callback?code=mock_code&state=invalid_state');

    // Verify CSRF validation error
    const csrfError = page.getByText(/invalid state|csrf|security/i);
    await expect(csrfError).toBeVisible();

    // Verify redirect back to login
    await expect(page).toHaveURL(/login/);
  });
});
